package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.introspect.AnnotatedParameter;
import com.fasterxml.jackson.databind.introspect.AnnotatedWithParams;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class ValueInstantiator_getValueTypeDesc_TriageGen1Test {

    @Mock
    private ValueInstantiator valueInstantiator;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
    }

    @Test
    public void testGetValueTypeDesc_WhenClassIsNull_ReturnsUnknown() {
        // Arrange
        when(valueInstantiator.getValueClass()).thenReturn(null);

        // Act
        String result = valueInstantiator.getValueTypeDesc();

        // Assert
        assertEquals("UNKNOWN", result);
    }

    @Test
    public void testGetValueTypeDesc_WhenClassIsNotNull_ReturnsClassName() {
        // Arrange
        Class<?> targetClass = String.class;
        when(valueInstantiator.getValueClass()).thenReturn(targetClass);

        // Act
        String result = valueInstantiator.getValueTypeDesc();

        // Assert
        assertEquals("java.lang.String", result);
    }

    @Test
    public void testGetValueTypeDesc_WhenClassIsInteger_ReturnsClassName() {
        // Arrange
        Class<?> targetClass = Integer.class;
        when(valueInstantiator.getValueClass()).thenReturn(targetClass);

        // Act
        String result = valueInstantiator.getValueTypeDesc();

        // Assert
        assertEquals("java.lang.Integer", result);
    }
}
